# Lanternhold v141 Ember Ring (John, 27 Nov 2026). Paste into AWS CloudShell (us-east-1). Needs John's go.
# Updates lanternhold-arena:
#  - dungeon power no longer counts (the game used to send it and could fake it); each class has its own Ring base
#  - Ring Mastery: after the full kit, 500 Laurels a rank, +1% Ring health and attack, up to 10
#  - monthly seasons (Season 1 ends 31 Dec 2026): soft reset, saved standings, award cosmetics on the winners' wallets
# Adds env WALLETS and UpdateItem on the wallets table to the arena role (for the season awards).
# Stops if the live code is not the v140 code it expects. Backs up the function to ~/lhbak and prints the undo command.
set -e
F=lanternhold-arena; T=$(date -u +%Y%m%d%H%M); mkdir -p ~/lhbak ~/lhv141r && cd ~/lhv141r
curl -s -o live.zip "$(aws lambda get-function --function-name $F --query Code.Location --output text)"
[ "$(unzip -p live.zip index.js | md5sum | cut -c1-32)" = "f4e484a4187f6b1a16d1cd01b466653b" ] || { echo "lanternhold-arena is not the v140 code this script expects. Stopping; nothing changed. Ask Claude."; exit 1; }
cp live.zip ~/lhbak/$F-$T.zip; echo "backup: ~/lhbak/$F-$T.zip"
echo  | base64 -d > index.js
[ "$(md5sum index.js | cut -c1-32)" = "bbb55305c841941747056eac62c0b33d" ] || { echo "The code did not paste cleanly. Nothing changed."; exit 1; }
# 1. wallets access + env (kept alongside the other variables)
WT=$(aws dynamodb describe-table --table-name lanternhold-wallets --query Table.TableArn --output text)
ROLE=$(aws lambda get-function-configuration --function-name $F --query Role --output text | awk -F/ '{print $NF}')
aws iam put-role-policy --role-name "$ROLE" --policy-name lanternhold-v141-wallets --policy-document "{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Action\":\"dynamodb:UpdateItem\",\"Resource\":\"$WT\"}]}"
aws lambda get-function-configuration --function-name $F --query Environment > env.json
python3 -c "import json; e=json.load(open('env.json')) or {}; v=e.get('Variables',{}); v['WALLETS']='lanternhold-wallets'; print(json.dumps({'Variables':v}))" > env2.json
aws lambda update-function-configuration --function-name $F --environment file://env2.json >/dev/null
aws lambda wait function-updated --function-name $F
echo "env WALLETS set, wallets access added"
# 2. the code
rm -f ring.zip && zip -qj ring.zip index.js
aws lambda update-function-code --function-name $F --zip-file fileb://ring.zip >/dev/null
aws lambda wait function-updated --function-name $F
echo "done. Undo: aws lambda update-function-code --function-name $F --zip-file fileb://$HOME/lhbak/$F-$T.zip"
